import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import * as ed from "@noble/ed25519";
import { describe, expect, it } from "vitest";
import { canonicalJson, utcStamp } from "./canonical";
import { fromB64, signObject, toB64, verifyObject } from "./keys";

// shared/*.json are generated by the BACKEND (shared/make_fixture.py); backend/tests/test_crypto.py
// checks the same files, so a drift on either side fails a test.
const shared = (name: string) => JSON.parse(readFileSync(resolve(__dirname, "../../shared", name), "utf-8"));

describe("canonicalJson", () => {
  it("matches the backend byte for byte (shared fixture)", () => {
    const fx = shared("canonical_fixture.json");
    expect(canonicalJson(fx.input)).toBe(fx.expected);
  });

  it("whole numbers have no decimal point, others keep it", () => {
    expect(canonicalJson({ a: 5.0, b: 4.5, c: -3.0, d: 0.0 })).toBe('{"a":5,"b":4.5,"c":-3,"d":0}');
  });

  it("sorts keys recursively and uses compact separators", () => {
    expect(canonicalJson({ b: 1, a: { d: [1, { z: 1, y: 2 }], c: null } })).toBe('{"a":{"c":null,"d":[1,{"y":2,"z":1}]},"b":1}');
  });

  it("is ASCII only", () => {
    const out = canonicalJson({ n: "é☃😀\u007f" });
    expect(out).toBe('{"n":"\\u00e9\\u2603\\ud83d\\ude00\\u007f"}');
    expect([...out].every((c) => c.charCodeAt(0) < 128)).toBe(true);
  });

  it("utcStamp drops milliseconds", () => {
    expect(utcStamp(new Date("2026-11-05T12:00:00.789Z"))).toBe("2026-11-05T12:00:00Z");
  });
});

describe("signatures are interoperable with the backend (PyNaCl)", () => {
  const fx = shared("signed_fixture.json");

  it("verifies the server-signed certificate and device-signed voucher", async () => {
    const serverKey = fx.server_pubkey_b64;
    expect(await verifyObject(serverKey, fx.certificate, fx.cert_signature)).toBe(true);
    expect(await verifyObject(fx.certificate.device_pubkey, fx.voucher, fx.device_signature)).toBe(true);
    expect(await verifyObject(fx.certificate.device_pubkey, { ...fx.voucher, serial: 3 }, fx.device_signature)).toBe(false);
  });

  it("signing the voucher in JS yields the exact bytes Python produced (Ed25519 is deterministic)", async () => {
    const secret = fromB64(fx.device_seed_b64);
    expect(toB64(await ed.getPublicKeyAsync(secret))).toBe(fx.certificate.device_pubkey);
    expect(await signObject(secret, fx.voucher)).toBe(fx.device_signature);
  });
});
